eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   BLOG_POSTS: () => (/* binding */ BLOG_POSTS),\n/* harmony export */   CATEGORY_ACCENTS: () => (/* binding */ CATEGORY_ACCENTS),\n/* harmony export */   CATEGORY_LABELS: () => (/* binding */ CATEGORY_LABELS),\n/* harmony export */   getAllPosts: () => (/* binding */ getAllPosts),\n/* harmony export */   getPostBySlug: () => (/* binding */ getPostBySlug)\n/* harmony export */ });\nconst BLOG_POSTS = [\n    {\n        slug: \"how-to-pay-yourself-from-an-llc\",\n        title: \"How to Pay Yourself from an LLC Without Getting Wrecked by the IRS\",\n        excerpt: \"Single-member, multi-member, S-corp elected — the way you pay yourself changes with each. Here is the plain-English map to owner draws, guaranteed payments, and reasonable comp.\",\n        category: \"money\",\n        author: \"Hidden Library\",\n        publishedAt: \"2026-07-17\",\n        readingMinutes: 8,\n        productSlug: \"how-to-pay-yourself-from-an-llc\",\n        productTitle: \"How to Pay Yourself from an LLC — Complete Guide\",\n        content: [\n            {\n                type: \"p\",\n                text: 'The single most common question new LLC owners ask their accountant in the first ninety days: \"How do I actually pay myself?\" It sounds like it should be simple. It is not — and the wrong answer will show up on your tax return as an audit flag, a payroll penalty, or both.'\n            },\n            {\n                type: \"p\",\n                text: \"The right answer depends on how your LLC is taxed. Not what it is called — how it is taxed. That distinction is the entire game.\"\n            },\n            {\n                type: \"divider\"\n            },\n            {\n                type: \"h2\",\n                text: \"The three tax classifications that decide everything\"\n            },\n            {\n                type: \"p\",\n                text: \"Every LLC in the United States falls into one of three tax buckets. Whichever bucket you sit in decides how money moves from the business to your personal account, whether you run payroll, and how much of that money is subject to self-employment tax.\"\n            },\n            {\n                type: \"ol\",\n                items: [\n                    \"Single-member LLC (default) — taxed as a sole proprietorship. You take owner draws.\",\n                    \"Multi-member LLC (default) — taxed as a partnership. You take guaranteed payments plus distributive share.\",\n                    \"LLC that elected S-corp status (Form 2553) — you become a W-2 employee of your own company plus take distributions.\"\n                ]\n            },\n            {\n                type: \"h3\",\n                text: \"1. Single-member LLC: the owner draw\"\n            },\n            {\n                type: \"p\",\n                text: \"You do not run payroll on yourself. You do not send yourself a W-2. You transfer money from the business checking account to your personal checking account and call it an owner draw. That transfer is not a business expense — it does not reduce your taxable income. The entire profit of the LLC is taxed to you personally whether you draw it or leave it in the account.\"\n            },\n            {\n                type: \"callout\",\n                title: \"The trap most first-timers fall into\",\n                text: 'They see cash in the business account and assume it is \"revenue\" they can spend. It is not — a chunk of it is already earmarked for federal income tax, state income tax, and 15.3% self-employment tax. Set aside 25–30% of every profit dollar the day it lands.'\n            },\n            {\n                type: \"h3\",\n                text: \"2. Multi-member LLC: guaranteed payments plus distributive share\"\n            },\n            {\n                type: \"p\",\n                text: \"A multi-member LLC is a partnership by default. If you actively work in the business, the operating agreement should specify a guaranteed payment — a fixed amount paid to you regardless of profit, similar to a salary but reported on your K-1, not a W-2. Anything above that comes as your distributive share of profit.\"\n            },\n            {\n                type: \"h3\",\n                text: \"3. S-corp elected LLC: reasonable compensation plus distributions\"\n            },\n            {\n                type: \"p\",\n                text: 'This is the setup people mean when they say \"elect S-corp to save on taxes.\" You put yourself on payroll at a reasonable salary, withhold and remit payroll taxes on that portion, then take the remaining profit as a distribution — which is not subject to self-employment tax. The savings can be real. So can the audit exposure if your salary is unreasonably low.'\n            },\n            {\n                type: \"divider\"\n            },\n            {\n                type: \"h2\",\n                text: \"The one number that decides whether the S-corp game is worth it\"\n            },\n            {\n                type: \"p\",\n                text: \"Rough rule of thumb: below roughly $60–80k in net profit, the S-corp election is not worth the payroll costs, the extra tax return (Form 1120-S), and the ongoing compliance overhead. Above that, the self-employment tax savings start to genuinely outrun the friction. Numbers vary by state — do not commit until you have run yours.\"\n            },\n            {\n                type: \"quote\",\n                text: '\"Pay yourself in a way you can defend to an auditor with a straight face.\"',\n                cite: \"Every CPA, ever\"\n            },\n            {\n                type: \"h2\",\n                text: 'What \"reasonable compensation\" actually means'\n            },\n            {\n                type: \"p\",\n                text: \"The IRS does not publish a table. What they look at: what a business would pay an unrelated third party to perform the same role in your industry, in your geography, at your revenue level. If you run a $500k marketing agency and pay yourself $20k in salary while taking $380k in distributions, you are inviting the wrong kind of attention.\"\n            },\n            {\n                type: \"ul\",\n                items: [\n                    \"Bureau of Labor Statistics wage data is a defensible starting point.\",\n                    \"Trade association surveys are stronger — they show what your specific role earns.\",\n                    \"RCReports (paid tool) is what many CPAs use to generate a defensible number.\"\n                ]\n            },\n            {\n                type: \"divider\"\n            },\n            {\n                type: \"h2\",\n                text: \"The playbook — what to actually do this week\"\n            },\n            {\n                type: \"ol\",\n                items: [\n                    \"Confirm your LLC tax classification (check your last return or ask your accountant).\",\n                    \"If single-member and you are earning under $60k net: keep taking draws and set aside 25–30% for taxes.\",\n                    \"If you are pushing past $80k net and have not made an S-corp election: run the numbers with a CPA before year end.\",\n                    \"If already S-corp: benchmark your salary against BLS/RCReports so it is defensible.\",\n                    \"Set up quarterly estimated tax payments so you are not staring at a five-figure April surprise.\"\n                ]\n            },\n            {\n                type: \"callout\",\n                title: \"Want the whole playbook, not just the map?\",\n                text: \"Our full guide walks through the exact spreadsheet, the operating agreement clauses, the payroll setup, and the estimated-tax schedule — with worked examples at $50k, $150k, and $400k profit. One-time $10, instant PDF, keep forever.\"\n            }\n        ]\n    }\n];\nfunction getAllPosts() {\n    return [\n        ...BLOG_POSTS\n    ].sort((a, b)=>new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());\n}\nfunction getPostBySlug(slug) {\n    return BLOG_POSTS.find((p)=>p.slug === slug);\n}\nconst CATEGORY_LABELS = {\n    money: \"Money\",\n    business: \"Business\",\n    career: \"Career\",\n    productivity: \"Productivity\",\n    \"financial-health\": \"Financial Health\"\n};\nconst CATEGORY_ACCENTS = {\n    money: \"#60a5fa\",\n    business: \"#c4b5fd\",\n    career: \"#fb923c\",\n    productivity: \"#a5b4fc\",\n    \"financial-health\": \"#86efac\"\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/blog-posts.ts\n");

